            if (match.getHouseholdId() != null) {
                householdId = match.getHouseholdId();
                break;
            }
        }
        owner.setHouseholdId(householdId);
        for (Owner match : matches) {
            if (!householdId.equals(match.getHouseholdId())) {
                match.setHouseholdId(householdId);
                ownerRepository.save(match);
            }
        }
    }

    /** Stable {@code 'HH-<16 hex>'} identifier for the household keyed by lastName+address. */
    private static String deriveHouseholdId(String lastName, String address) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest((lastName + "�" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder("HH-");
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02X", hash[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /** Last-name key: lower-cased, trimmed, with internal whitespace runs collapsed to one space. */
    private static String normalize(String value) {
        if (value == null) {
            return null;
        }
        String collapsed = value.trim().replaceAll("\\s+", " ");
        return collapsed.isEmpty() ? null : collapsed.toLowerCase(Locale.ROOT);
    }
}

